static double pv_dot(adcs_vec3_t a,adcs_vec3_t b){return a.x*b.x+a.y*b.y+a.z*b.z;}
static adcs_vec3_t pv_add(adcs_vec3_t a,adcs_vec3_t b){adcs_vec3_t r={a.x+b.x,a.y+b.y,a.z+b.z};return r;}
